#!/usr/bin/env bash
# Shared helpers for the setup scripts and the acts.
set -euo pipefail

DEMO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$DEMO_DIR"
source "$DEMO_DIR/config.env"

# Generated by setup (gitignored): unseal key, root token, IPs, DB passwords.
STATE="$DEMO_DIR/.state"
mkdir -p "$STATE" && chmod 700 "$STATE"
state() { cat "$STATE/$1" 2>/dev/null || true; }

# Local vault CLI -> IAP tunnel -> Vault VM.
export VAULT_ADDR="http://127.0.0.1:${VAULT_LOCAL_PORT}"
if [[ -f "$STATE/vault-init.json" ]]; then
  VAULT_TOKEN="$(jq -r .root_token "$STATE/vault-init.json")"
  export VAULT_TOKEN
fi
v() { vault "$@"; }

require_vault() {
  local rc=0
  vault status >/dev/null 2>&1 || rc=$?
  if [[ $rc == 1 ]]; then
    echo "Can't reach Vault at $VAULT_ADDR. Start the tunnel in another tab: ./scripts/tunnel.sh" >&2
    exit 1
  fi
  if [[ $rc == 2 ]]; then
    echo "Vault is sealed. Run ./scripts/unseal.sh" >&2
    exit 1
  fi
}

# MySQL as root, from a client pod inside the cluster (Cloud SQL has a private IP only).
mysql_admin() {
  kubectl exec -i -n db mysql-client -- \
    env MYSQL_PWD="$(state mysql-root-password)" \
    mysql -h "$(state sql-ip)" -u root "$@"
}

# Narration line, shown in cyan.
say() { printf '\n\033[1;36m# %s\033[0m\n' "$*"; }

# Print a command in yellow, wait for Enter, then run it.
# AUTO=1 ./acts/act2-vault-kv-injector.sh runs without pauses.
step() {
  printf '\n\033[1;33m$ %s\033[0m' "$*"
  if [[ "${AUTO:-0}" != 1 ]]; then read -r -s; fi
  echo
  eval "$@" || printf '\033[0;31m(exit %s)\033[0m\n' "$?"
}
